#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Single address source for GPU assembly, 68000 C, and emulator assertions."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
a={'OBJECT_LIST':0x800,'CAMERA_X':0x900,'CAMERA_Y':0x904,'CAMERA_Z':0x908,'CAMERA_ANGLE_Y':0x90c,'CAMERA_SPEED':0x910,'LIGHT_X':0x914,'LIGHT_Y':0x918,'LIGHT_Z':0x91c,'RLIGHT_X':0x920,'RLIGHT_Y':0x924,'RLIGHT_Z':0x928,'OBJECT_PTR':0x92c,'USE_GOURAUD':0x948,'USE_PHRASE':0x94c,'IS_PAL':0x950,'LastJoy':0x954,'plane_y':0x40000,'plane_col':0x48000,'plane_normals':0x50000,'plane_vnormals':0x90000,'texture':0xb0000,'SCENE_OBJECTS':0xe0000,'SCENERY_DRAW_CACHE':0xe1000,'SCENERY_COLLISION_CACHE':0xf0000,'REPLAY_FRAMES':0xf8000,'TELEMETRY':0x1000,'tri_ptrs_ram':0x190000,'tri_array_ram':0x191000,'tri_array_end':0x1b4000}
p=0x110000;np=24*24;nf=2*23*23
for name,n in [('plane_rotated',4+np*8),('plane_projected',4+np*8),('plane_normals_rotated',4+nf*8),('plane_vnormals_rotated',4+np*8),('plane_visible',4+nf*4),('plane_faces',4+nf*12)]:
    a[name]=p;p=(p+n+31)&~31
a['OBJECT_SCRATCH']=p;a['SCRATCH_END']=a['tri_ptrs_ram']
(R/'src/gpu/memory.inc').write_text('; Generated by tools/memory_map.py\n'+'\n'.join(f'{k} equ ${v:x}' for k,v in a.items())+'\n')
(R/'src/memory.h').write_text('/* Generated by tools/memory_map.py */\n#ifndef TR_MEMORY_H\n#define TR_MEMORY_H\n'+'\n'.join(f'#define ADDR_{k} 0x{v:x}u' for k,v in a.items())+'\n#endif\n')
(R/'assets/memory.json').write_text(json.dumps(a,indent=2)+'\n')
